-- ===== UG51302UG51303 : قرار 133/2020 =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (133, 2020, $t28$بشأن ضوابط المساهمة فى رأس مال شركات التأمين$t28$, $t28$بشأن ضوابط المساهمة فى رأس مال شركات التأمين$t28$, 'insurance', 'in_force', $u28$https://fra.gov.eg/wp-content/uploads/fra_live_data/pdfs/UG51302UG51303.pdf$u28$, NULL)
ON CONFLICT (law_no, law_year) DO NOTHING;

WITH ins_art_UG51302UG51303_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b29$مع عدم الإخلال بأحكام المادتين (0؟ مكررأ 21 ٠ 4) من قانون الإشراف والرقابة على التأمين في مصر وقرار
مجلس إدارة الهيئة رقم (57) لسنة 7٠١١4 بشأن ضوابط منح الترخيص واستمراره وقواعد تملك أسسهم الشركات
العاملة في الأنشطة المالية غير المصرفية؛ لا يجوز للأشخاص الطبيعيين أو الاعتباريين الذين يتملكون حصة
مسيطرة في إحدى شركات التأمين» المساهمة بشكل مباشر أو غير مباشر ويمفردهم أو من خلال أطرافهم المرتبطة.
إلا في شركة تأمين واحدة أخرى تزاول ذات النشاط وينسبة تقل عن (9075!) من أسهم تلك الشركة أو حقوق
التصويت يها.
ويجوز زيادة نسبة المساهمة بما يجاوز النسبة المذكورة بالفقرة السابقة إذا اقترن طلب التملك بتقديم خطة ملزمة
لاندماج شركتي التأمين المشار إليهماء على أن يتم تنفيذ عملية الاندماج خلال سنة بحد أقصى من تاريخ تقديم
القرية الذكية: مبنى 111 الجيزة: مصر
الرقمالبريدى 1١١١
تليفون: +17١7507076٠ فاكس ١15 .تلن" ال 4 5الةلاا أمم 5عو800 ووألاأناد8
