-- ===== alamiria_2024_237 : قرار 237/2024 =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (237, 2024, $t43$بشأن ضوابط تسجيل وتصفية وشطب صناديق التأمين الخاصة والشروط الواجب توافرها فى النظام الأساسي لتلك الصناديق وضوابط تعديلها$t43$, $t43$بشأن ضوابط تسجيل وتصفية وشطب صناديق التأمين الخاصة والشروط الواجب توافرها فى النظام الأساسي لتلك الصناديق وضوابط تعديلها$t43$, 'insurance', 'in_force', $u43$https://fra.gov.eg/wp-content/uploads/2024/11/alamiria_2024_237.pdf$u43$, NULL)
ON CONFLICT (law_no, law_year) DO NOTHING;

