INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (298, 2024, $t65$بشأن ضوابط قيد المتدربين على أعمال الوساطة التأمينية لدى الهيئة وقواعد ممارستهم لأعمال التدريب بشركات التأمين وإعادة التأمين وشركات الوساطة التأمينية$t65$, $t65$بشأن ضوابط قيد المتدربين على أعمال الوساطة التأمينية لدى الهيئة وقواعد ممارستهم لأعمال التدريب بشركات التأمين وإعادة التأمين وشركات الوساطة التأمينية$t65$, 'insurance', 'in_force', $u65$https://fra.gov.eg/wp-content/uploads/2025/01/alamiria_2024_298.pdf$u65$, NULL)
ON CONFLICT (law_no, law_year) DO NOTHING;

WITH ins_art_alamiria_2024_298_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b66$نطاق التطبيق
تسرى أحكام هذا القرار بشأن ضوابط قيد المتدربين على أعمال الوساطة
التأمينية لدى الهيئة وقواعد ممارستهم لعملهم بشركات التأمين أو إعادة التأمين
 أو الوساطة التأمينية .
ولا يجوز لهؤلاء المتدربين القيام بأعمال الوساطة التأمينية إلا بعد قيدهم بالسجل
 المعد لهذا الغرض بالهيئة بمراعاة الضوابط الواردة بهذا القرار .$b66$
  FROM laws WHERE law_no = 298 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $b66$نطاق التطبيق
تسرى أحكام هذا القرار بشأن ضوابط قيد المتدربين على أعمال الوساطة
التأمينية لدى الهيئة وقواعد ممارستهم لعملهم بشركات التأمين أو إعادة التأمين
