-- ===== alamiria_2025_306-1 : قرار 306/2025 =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (306, 2025, $t110$بشأن تعديل النظام الأساسي للمجمعة المصرية لتأمين الأخطار النووية$t110$, $t110$بشأن تعديل النظام الأساسي للمجمعة المصرية لتأمين الأخطار النووية$t110$, 'insurance', 'in_force', $u110$https://fra.gov.eg/wp-content/uploads/2026/01/alamiria_2025_306-1.pdf$u110$, NULL)
ON CONFLICT (law_no, law_year) DO NOTHING;

WITH ins_art_alamiria_2025_306_1_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b111$يستبدل بنص المادة ) (۲من النظام الأساسى للمجمعة المصرية لتأمين الأخطار
 النووية النص التالى :
المادة - ۲غرض المجمعة المصرية لتأمين الأخطار النووية القيام ونيابة عن
الشركات الأعضاء ولحسابهم -بإدارة كل ما يتعلق بالعمليات التأمينية من تأمين
وإعادة تأمين وكذا الحساب المشترك للشركات الأعضاء وتقوم المجمعة في سبيل
 تحقيق ذلك الغرض بالعمليات التالية :
 -١التأمينات المتعلقة بإقامة وتركيب المنشآت النووية ،بدءا من عمليات التجهيز
 للموقع والنقل البحري والتخزين وحتى إتمام عملية الإنشاء والتجارب .
 -٢التأمين على مسئولية القائم بالتشغيل طبق ًا للقوانين المصرية المنظمة للأنشطة
النووية والإشعاعية واللوائح التنفيذية والقرارات المنظمة لها وكذلك المعاهدات الدولية
 الموقعة من جمهورية مصر العربية والمنظمة لهذه المسئولية .
 الوقائع المصریة – العدد ٢٩٥تابع )ج( فى ٣٠دیسمبر سنة ٢٠٢٥ ١٢
 -٣التأمين من الأضرار المادية الناتجة عن التشغيل والتى تلحق بالمنشآت النووية .
 -٤تأمين الأخطار الأخرى المتعلقة بالمنشآت النووية .
 -٥التعاون في مجال تأمين الأخطار النووية مع المجمعات المثيلة فى العالم .
 -٦قبول حصص إعادة تأمين من مجمعات تأمين الأخطار النووية فى نطاق
 الحدود والشروط التي ينظمها هذا النظام واللوائح الداخلية للمجمعة .$b111$
  FROM laws WHERE law_no = 306 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
