WITH ins_art_alamiria_2026_57_4 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 4, NULL, $b192$صورة إ
تتولي الإدارة المختصة تلقي التظلم ومرفقاته وتقوم بقيده بالسجل المعد لذلك في
 يوم وروده ،وعليها تسليم المتظلم صورة من تظلمه مثبتا ً عليها رقم القيد وتاريخه .
 لك
ويعرض التظلم علي رئيس الهيئة أو من يحل محله لتحديد اللجنة المختصة
 تروني
 بنظره ،وتعيين ممثل الهيئة باللجنة .
ويتم عرض التظلم علي رئيس اللجنة المختصة لتحديد موعد نظر التظلم،
 ة ال يع
على أن يخطر المتظلم بتاريخ الجلسة بخطاب مسجل مصحوب بعلم الوصول
أو بالبريد الإلكتروني ،أو باستخدام الرسائل النصية على رقم هاتفه المسجل لدي الهيئة .$b192$
  FROM laws WHERE law_no = 57 AND law_year = 2026
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
