WITH ins_art_alamiria_2026_98_2 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 2, NULL, $b216$يجب على شركات التأمين إعداد برنامج لإعادة التأمين يتناسب مع رأس مال
 الشركة وحجم نشاطها ،على أن يتضمن بحد أدنى البنود الآتية :
 - ١حدود المخاطر المقبولة من حيث إجمالي مبالغ التأمين وصافي الاحتفاظ
 وسياسة الشركة في تحديد ذلك .
 -۲بيان بمبررات تنوع أشكال وطرق إعادة التأمين ضمن البرنامج .
 -٣تحديد التغطية والحدود والأولوية لكل اتفاقية ضمن البرنامج .
 -٤بيان أقصى التزام مالي يمكن للشركة أن تتحمله نتيجة لخطر أو حدث
 واحد ،مع بيان مدى تأثيره على المحفظة .
 -٥بيان حالات لجوء الشركات واعتمادها على الإسناد الاختياري
 ومتابعة إجراءاته .
كما تلتزم شركات التأمين بوضع إجراءات لتقييم وإدارة الخطر في إعادة
 التأمين ،على أن تتضمن تلك الإجراءات ما يلي :
 - ۱مراقبة وتحليل مخاطر إعادة التأمين التي قد تتعرض لها الشركة بشكل
 دوري ،مع مواجهة تلك المخاطر في وقت مناسب ومبكر .
