WITH ins_art______________199______2025__________2 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 2, NULL, $b301$إجراءات الحصول على موافقة الهيئة على إصدار وتوزيع وثائق التأمين رقميا
تلتزم شركات التأمين الراغبة في إصدار وإتاحة توزيع وثائقها رقميا بتقديم طلب
 للهيئة بذلك مرفق ًا به ما يلي :
 - ١بيان بإجراءات العمل التي ستتبعها الشركة لإصدار وتوزيع وثائق التأمين
بما في ذلك استيفاء كافة المتطلبات التأمينية لإصدار تلك الوثائق ،وكذا تعريف العميل
بالمنتج التأميني وشروطه بشكل مكتوب ومن خلال فيديو تعريفي ،وما يفيد التحقق
 رقميا من اطلاعه على كافة شروط الوثيقة والمخاطر المرتبطة بها وقبوله لهما .
 - ۲تعهد بالالتزام بقرارات مجلس إدارة الهيئة أرقام ۱٤۱ ،۱٤۰ ،۱۳۹
 لسنة ٢٠٢٣المشار إليها .
 صورة إ
وتتولى الهيئة دراسة الطلب المشار إليه ،ولها طلب استيفاء أي بيانات
أو مستندات ترى ضرورة تقديمها للبت في الطلب ،وتبت الهيئة في الطلب المقدم إليها
 لك
خلال ثلاثين يوما على الأكثر من تاريخ تقديمه مستوفيا المستندات المؤيدة له ،على أن
 تروني
يراعى عند دراسة الطلب والبت فيه مدى صدور أحكام قضائية أو تدابير إدارية
 ة ال يع
 أو إجراءات رقابية ضد الشركة خلال السنتين السابقتين على تقديم طلب الموافقة .$b301$
  FROM laws WHERE law_no = 199 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
