INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $b330$اللجان الواجب تشكيلها بالشركة
 ة ال يع
يلتزم مجلس الإدارة بتشكيل لجان لدعمه فى القيام بالدور المنوط به وتحسين
فعالية وكفاءة واستقلالية اتخاذ القرارات داخل المجلس ،وتعزيز الرقابة والحوكمة
 تد بها
بالشركة على نحو يتناسب مع حجم أعمالها وطبيعة نشاطها ومستوى المخاطر التى
 تواجهها ،على النحو الآتى :
 عند ا
 -١لجنة الترشيحات والمكافآت .
 -٢لجنة المراجعة الداخلية .
 ل
 تداول
 -٣لجنة المخاطر .
 -٤لجنة الاستثمار .
 الوقائع المصریة – العدد ) ٢٣٥تابع( فى ٢١أكتوبر سنة ٢٠٢٥ ٢٤
 -٥لجنة الحوكمة .
 -٦لجنة حماية حقوق حملة الوثائق .
وفى جميع الأحوال ،لا يجوز دمج أى من تلك اللجان ،كما لا يجوز تماثل
 كامل تشكيل أى منها .
 كما يتعين على المجلس تشكيل اللجان الآتية :
 -١لجنة تكنولوجيا المعلومات والتحول الرقمي
 -٢لجنة تطوير المنتجات التأمينية .
 -٣لجنة إدارة الأصول والالتزامات .
 -٤لجنة الممارسات البيئية والمجتمعية والحوكمة المتعلقة بالاستدامة
 والحوكمة المناخية .
ويجب أن يكون لكل لجنة من اللجان المشكلة من مجلس الإدارة ميثاق تنظيمى
وفق الضوابط الواردة بهذا القرار يعتمد من مجلس إدارة الشركة يتضمن تحديد
 صورة إ
 اختصاصاتها ومسئولياتها وبحد أدنى ما يلى :
 -١آليات تشكيل اللجنة ،واختصاصاتها ،ومسئولياتها ،ونطاق ومدة عملها .
 لك
 -٢النصاب القانونى لصحة انعقاد اجتماعاتها .
 تروني
 -٣عدد الاجتماعات التى يجب أن تعقدها اللجنة .
 -٤آلية إعداد محاضر الاجتماعات ،ودورية عرض التقارير على مجلس
 ة ال يع
 الإدارة بشأن نتائج أعمالها .
