WITH ins_art______________200______2025__________24 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 24, NULL, $b332$لجنة الترشيحات والمكافآت
 تختص لجنة الترشيحات والمكافآت بحد أدنى بما يلى :
 -١تحديد مسئوليات أعضاء مجلس الإدارة التنفيذيين وغير التنفيذيين والمستقلين
 وإعداد الوصف الوظيفى للقائمين على الإدارة التنفيذية العليا .
 -٢إجراء مراجعة دورية ومستمرة لاحتياجات الشركة من المهارات والخبرات
المناسبة لعضوية مجلس الإدارة ،والإدارة التنفيذية العليا ،وإعداد بيان بالمؤهلات
 المطلوبة .
 -٣رفع التوصيات إلى مجلس الإدارة بترشيح التخصصات أو الأشخاص
ممن تراه اللجنة مناسبا لعضوية مجلس الإدارة من المستقلين أو عضوية لجانه ،
وفق ًا للمتطلبات النظامية والسياسات والمعايير المعتمدة ،وكذلك التوصية بتعيين
 أو إعفاء أى من الإدارة التنفيذية العليا .
 صورة إ
 -٤تقييم هيكل تشكيل مجلس الإدارة ولجانه ،وتحديد جوانب الضعف بصفة
 دورية ،واقتراح الإجراءات اللازمة لمعالجتها .
 لك
 -٥التأكد من وجود آلية فعالة لتقييم أداء مجلس الإدارة ولجانه ،وتطبيقها بشكل
 تروني
 فعال مرة واحدة على الأقل سنويا .
 -٦الإشراف على تنفيذ البرنامج التعريفى والتدريب الدورى لأعضاء مجلس
 ة ال يع
 الإدارة .
 -٧إعداد سياسات واضحة بشأن المكافآت والبدلات والاستحقاقات الخاصة
 تد بها
بأعضاء مجلس الإدارة وأعضاء اللجان والإدارة التنفيذية العليا ،بما فى ذلك العضو
المنتدب /الرئيس التنفيذى ،ويجب الاستعانة بمعايير تربط تلك السياسات بمعايير أداء
محددة ،على أن يتم مراجعة تلك السياسات بصورة سنوية بناء على دراسات
 عند ا
 واستقصاءات مستقلة ودون تدخل من الإدارة التنفيذية بالشركة .
 ل
 -٨مراجعة خطة التعاقب الوظيفى ،والتأكد من كفاءة تطبيقها .
 تداول
 -٩وضع سياسة ترشيح واختيار الإدارة التنفيذية العليا بالشركة ،بالإضافة إلى
وضع سياسة لضمان استمرارية ملاءمة وتناسب الأشخاص المرشحين أو شاغلى تلك
٢٧ الوقائع المصریة – العدد ) ٢٣٥تابع( فى ٢١أكتوبر سنة ٢٠٢٥
الوظائف بما يتوافق مع التشريعات الصادرة فى هذا الشأن ،على أن يتم تحديث هذه
 السياسات بشكل دورى واعتمادها من مجلس الإدارة .
ويجوز للشركة فصل اختصاصات تلك اللجنة وتشكيل لجنتين مستقلتين أحدهما
 للترشيحات والأخرى للمكافآت على أن تحدد اختصاصات كل منهما بوضوح .$b332$
  FROM laws WHERE law_no = 200 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
