WITH ins_art______________200______2025__________27 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 27, NULL, $b335$لجنة الاستثمار
 تختص لجنة الاستثمار بحد أدنى بما يلى :
 -١معاونة مجلس الإدارة فى توظيف أموال الشركة فى استثمارات تحقق أفضل
عوائد وذلك وفق ًا للسياسة الاستثمارية المعتمدة من مجلس الإدارة ،وبما يمكن الشركة
 من تعظيم عوائد العملاء والوفاء بالتزاماتها قصيرة وطويلة الأجل .
 -٢مراجعة أداء السياسة الاستثمارية ،وكذا أداء كل فئة من الأصول .
 صورة إ
 -٣متابعة المخاطر العامة المرتبطة بالسياسة الاستثمارية للشركة .
 -٤رفع تقرير بنتائج أداء المحفظة الاستثمارية إلى مجلس الإدارة .
 لك
 -٥التحقق من الالتزام بالقرارات المتعلقة بالاستثمار الصادرة عن الهيئة .
 تروني
 -٦التنسيق الكامل مع كل من لجنة المخاطر ولجنة إدارة الأصول والالتزامات
 فيما يتعلق باتخاذ القرارات الاستثمارية وإدارة السيولة داخل الشركة .
 ة ال يع
 -٧متابعة قيمة الاحتساب الدورى للقيمة عند الخطر ) (Value at Riskللمحفظة
الاستثمارية والتأكد من توافقها مع درجة تحمل المخاطر ) (Risk Toleranceالمحددة
 تد بها
 من قبل لجنة المخاطر ،والتوصية بالإجراءات المتبعة حال عدم التوافق معها .$b335$
  FROM laws WHERE law_no = 200 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
