WITH ins_art______________200______2025__________38 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 38, NULL, $b346$عند ا
 إدارة المراجعة الداخلية
تلتزم الشركات المخاطبة بأحكام هذا القرار بإنشاء إدارة مستقلة للمراجعة الداخلية
 ل
 تداول
لمساعدتها على تحقيق أهدافها من خلال تبنى أسلوب منهجى ومنظم يهدف إلى تقييم
 وسائل ونظم الرقابة الداخلية ،والتأكد من سلامة تطبيق قواعد الحوكمة بها .
٣٩ الوقائع المصریة – العدد ) ٢٣٥تابع( فى ٢١أكتوبر سنة ٢٠٢٥
وتعرض إدارة المراجعة الداخلية تقاريرها على لجنة المراجعة الداخلية ،
ويتولى إدارة المراجعة الداخلية مسئول رئيسى متفرغ يتبع فنيا لجنة المراجعة الداخلية ،
ويتم تعيينه واستبداله وتحديد معاملته المالية بناء على توصية لجنة المراجعة الداخلية ،
ولا يجوز تعديل معاملته المالية أو أى مزايا يحصل عليها دون الرجوع للجنة
 المراجعة الداخلية .
وتحدد نظم وإجراءات المراجعة الداخلية بناء على دراسة للمخاطر التى تواجهها
الشركة ،على أن يستعان فى ذلك بالتوصيات والتقارير الصادرة عن لجان مجلس
 الإدارة ومراقبى الحسابات والخبراء الإكتواريين والمسئولين الرئيسيين بالشركة .
 وتختص إدارة المراجعة الداخلية بحد أدنى بما يلى :
 -١تقييم مدى كفاءة نظام الرقابة الداخلية بالشركة ،ورفع التقارير للجنة
 المراجعة الداخلية بالملاحظات فى هذا الشأن .
 صورة إ
 -٢تقييم مدى التزام جميع إدارات الشركة بتنفيذ أعمالها وفق ًا لإجراءات العمل
 والسياسات داخل الشركة دون التعارض مع اختصاصات الإدارات المعنية الأخرى .
 لك
 -٣التحقق من تحديث ومتابعة وتقييم المخاطر بشكل دورى .
 تروني
 -٤تقييم كفاءة الإجراءات والسياسات داخل الشركة وبيان مدى تناسبها مع
 تطورات العمل والسوق .
 ة ال يع
 -٥متابعة استيفاء الملاحظات الواردة بتقارير المراجعة الداخلية والخارجية
 والواردة من الهيئة .
 ويحب على الشركة الالتزام بما يلى :
 تد بها
 -١منح المسئول عن إدارة المراجعة الداخلية كافة الصلاحيات اللازمة للقيام
 بعمله على أكمل وجه .
 عند ا
 -٢توفير الوسائل والأدوات والتجهيزات اللازمة للإدارة للقيام بعملها بكفاءة .
 -٣توفير قنوات اتصال مباشرة ومستقلة بين إدارة المراجعة الداخلية ومجلس
 ل
 تداول
الإدارة ولجانه ،مع ضرورة التأكد من سهولة حصول العاملين بإدارة المراجعة
 الداخلية على كافة التقارير والمعلومات ذات الصلة بعملهم .
 الوقائع المصریة – العدد ) ٢٣٥تابع( فى ٢١أكتوبر سنة ٢٠٢٥ ٤٠$b346$
  FROM laws WHERE law_no = 200 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
