WITH ins_art______________200______2025__________42 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 42, NULL, $b350$تقارير الإفصاح
تلتزم الشركات المخاطبة بأحكام هذا القرار بالشفافية والدقة والشمول والحيادية
فى تقارير الإفصاح التى تعدها ،كما يجب عليها مراعاة أن تكون بيانات التقارير
والأرقام الواردة بها قابلة للمقارنة ،وأن تتناسب المعلومات الواردة بها مع احتياجات
المساهمين والأطراف ذات العلاقة بحسب الأحوال ،بالإضافة إلى الحرص على إتاحة
هذه التقارير بصورة دورية بما يسمح بتوفير المعلومات فى الوقت المناسب للأطراف
 ذات العلاقة لمساعدتهم فى اتخاذ القرار .$b350$
  FROM laws WHERE law_no = 200 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
