WITH ins_art______________230______2025__________3 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 3, NULL, $b362$إجراءات قيد شركات إعادة التأمين وفروعها لدى الهيئة
يقدم طلب قيد شركة إعادة التأمين أو فروعها بالقائمة من قبل الممثل القانوني
للشركة أو الفرع أو من شركة التأمين الراغبة في التعامل مع أي منهما ،وذلك على
 النموذج المعد لهذا الغرض بالهيئة مرفق ًا به المستندات الآتية :
 -١الترخيص بمزاولة نشاط إعادة التأمين صادر من الجهة الرقابية
 الخاضع لها .
 -٢أحدث تقرير تصنيف ائتماني دولي صادر عن إحدى وكالات التصنيف
 المبينة بالمادة الثانية من هذا القرار .
 -٣القوائم المالية لشركة إعادة التأمين باللغة الإنجليزية أو العربية وتقرير
 مراقب الحسابات المعتمد عن آخر ثلاث سنوات .
 -٤دراسة جدوى فنية تتعلق بنشاط معيد التأمين في سوق التأمين المصري،
على أن تتضمن بحد أدنى خطة العمل والخطة التشغيلية المستهدفة وبيان مدى
المساهمة في نقل الخبرات الفنية ،ويجوز للهيئة أن تطلب من شركة إعادة التأمين
 أو فروعها بحسب الأحوال إعداد عرض تقديمي واف لمشتملات الدراسة .
 -٥الهيكل التنظيمي لمعيد التأمين متضمن ًا أسماء المديرين الرئيسيين لديه ،
وأسماء الأشخاص المفوضين بالتوقيع على اتفاقيات أو عقود إعادة التأمين ،
 وكذا بيانات التواصل مع المعيد .
 -٦أي مستندات أو بيانات تطلبها الهيئة للبت في الطلب .$b362$
  FROM laws WHERE law_no = 230 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
