-- ===== نشر-قرار-رقم-69-لسنة-2023-بالوقائع : قرار 69/2023 =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (69, 2023, $t466$بشأن التزام شركات التأمين بتوفير البنية التكنولوجية اللازمة لربط بياناتها مع الهيئة$t466$, $t466$بشأن التزام شركات التأمين بتوفير البنية التكنولوجية اللازمة لربط بياناتها مع الهيئة$t466$, 'insurance', 'in_force', $u466$https://fra.gov.eg/wp-content/uploads/2023/05/%D9%86%D8%B4%D8%B1-%D9%82%D8%B1%D8%A7%D8%B1-%D8%B1%D9%82%D9%85-69-%D9%84%D8%B3%D9%86%D8%A9-2023-%D8%A8%D8%A7%D9%84%D9%88%D9%82%D8%A7%D8%A6%D8%B9.pdf$u466$, '7117-04-11')
ON CONFLICT (law_no, law_year) DO NOTHING;

WITH ins_art______________69______2023__________1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b467$تلتزم شركات التأمين بتوفير البنية التكنولوجية اللازمة لربط قاعدة بياناتها مع
قاعدة بيانات الهيئة وفقًا للضوابط التى تحددها الهيئة فى هذا الشأن .
وتلتزم شركات التأمين المشار إليها بإتاحة البيانات التالية للهيئة من خلال النظم
الالكترونية التى يتم إعدادها وفقًا للفقرة الأولى من هذه المادة :
. بيانات الأشخاص الذين تم رفض التعاقد معهم وأسباب الرفض -١
. بيانات العملاء المتعثرين والمتوقفين عن سداد القروض فى حالات تأمين الاثتمان -١
"- البيانات الخاصة بسجل الإصدار ؛ بما فى ذلك بيانات إصدار الوثائق وتعديلها
وإلغائها » وتسويات الإصدار » وتحصيل الأقساط .
الوقائع المصرية - العدد 65 (تابع) فى ١١ أبريل سنة ٠١571 3
4- البيانات الخاصة بسجل التعويضات » بما فى ذلك بيانات الإخطار » وسداد
التعويضات وتسويتها .
5- البيانات الخاصة بسجل الأموال المخصصة (ربط الأموال بأنواعها » إيرادات
الأموال » المصروفات المتعلقة بالأموال) .
5- البيانات الخاصة بسجل اتفاقيات إعادة التأمين وسجل العمليات الاختيارية
وأرصدة معيدى التأمين الدائنة والمدينة .
- بيانات مقار وفروع الشركة .
8- أى بيانات أخرى تطلبها الهيئة .
وتكون البيانات والمعلومات الخاصة بالعملاء والشركات أعلاه سرية ولا يجوز
إتاحتها إلا للهيئة » وتضع الهيئة الضوابط الخاصة بالتعامل عليها .
(المادة الشانية)
تمنح شركات التأمين المخاطبة بأحكام هذا القرار مهلة لمدة ستة أشهر لتوفيق
أوضاعها وافقًا الأحكانة » ويجوز مد لاه ألبيلة اللستة سير أقوىبالنسبة
للبنود (" 5٠ 56 16) الواردة بالمادة الأولى من هذا القرار » وذلك فى ضوء
المبررات التى تقدمها الشركة وتقبلها الهيئة .
المادة الشالشة)
ينشر هذا القرار فى الوقائع المصرية وعلى الموقع الالكترونى للهيئة » ويعمل به
من اليوم التالى لتاريخ نشره ٠
رئيس مجلس إدارة
الهيئة العامة للرقابة المالية
د/ محمد فريد صالح$b467$
  FROM laws WHERE law_no = 69 AND law_year = 2023
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
