INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $b476$إجراءات الترخيص والقيد بالسجل
يقدم طلب الترخيص بمزاولة النشاط على النموذج المعد من الهيئة لهذا الغرض ،
 مرفق ًا به المستندات الآتية :
 -١مستخرج رسمى من السجل التجارى للشركة .
 -٢صورة ضوئية من البطاقة الضريبية للشركة .
 -٣وثيقة تأمين مسئولية مهنية وفق ًا للضوابط الواردة بهذا القرار .
 -٤بيان بالهيكل التنظيمى للشركة .
 -٥بيانات أعضاء مجلس الإدارة ،وعلى وجه الأخص :الاسم والعنوان
والجنسية والمؤهل والصفة بالمجلس والخبرة السابقة خاصة فى مجال التأمين ونسبة
 المساهمة فى رأس مال الشركة .
 -٦الإفصاح عن مدى وجود صلة قرابة حتى الدرجة الثانية بين أى من أعضاء
مجلس إدارة الشركة وباقى أعضاء المجلس الآخرين أو مساهمى الشركة أو العاملين
 بها ،وكذا الإفصاح عن أى حالة من حالات تعارض المصالح .
 -٧إقرار بأنه لا يوجد من بين القائمين على إدارتها أى من شركات التأمين
 وإعادة التأمين أو أى من العاملين بها .
 الوقائع المصریة – العدد ) ١٢٨تابع( فى ١٢یونیة سنة ٢٠٢٥ ١٨
 -٨المستند الدال على سداد رسم تسجيل وقيد الشركة وفق ًا لقرار مجلس إدارة
 الهيئة الصادر فى هذا الشأن .
 -٩أى بيانات أو مستندات أخرى ترى الهيئة ضرورة تقديمها للبت فى الطلب .$b476$, now()::date, 'active' FROM ins_art______________69______2025__________8;
WITH ins_art______________69______2025__________9 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 9, NULL, $b477$البت فى طلب الترخيص والقيد بالسجل
تقوم الهيئة بالبت فى طلب الترخيص خلال ثلاثين يوما على الأكثر من تاريخ
تقديمه مستوفيا المستندات المتطلبة للبت فيه ،وفى حال رفض طلب الترخيص يجب
 أن يكون القرار مسببا .
ويصدر بترخيص الشركة وقيدها بالسجل قرارا من رئيس الهيئة أو من يفوضه ،
وينشر القرار على الموقع الإلكترونى للشركة وكذا الموقع الإلكترونى الذى تخصصه
 الهيئة لهذا الغرض .$b477$
  FROM laws WHERE law_no = 69 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
