INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $b490$الجمعية العامة لشركات الوساطة فى التأمين وإعادة التأمين
على شركة الوساطة فى التأمين أو إعادة التأمين دعوة الجمعية العامة للانعقاد
فى الزمان والمكان اللذين يعينهم نظام الشركة ويجب أن تعقد الجمعية مرة على الأقل
فى السنة خلال الثلاثة شهور التالية لنهاية السنة المالية للشركة ،ولمجلس الإدارة
 أن يقرر دعوة الجمعية العامة كلما دعت الضرورة إلى ذلك .
ويجب على مراقب الحسابات أن يدعو الجمعية العامة للانعقاد فى الأحوال التى
يتراخى فيها رئيس مجلس الإدارة عن دعوة الجمعية العامة للانعقاد خاصة خلال
 الثلاثة أشهر التالية لنهاية السنة المالية للشركة .
وتلتزم الشركة أن تقدم إلى الهيئة صورة من محضر اجتماع الجمعية العامة
 فى موعد أقصاه ثلاثين يوما من تاريخ انعقاد الجمعية لاعتماده .
وتلتزم الشركة بإدراج ما ترى الهيئة عرضه كبند من بنود جدول أعمال الجمعية
العامة للشركة ،وعلى رئيس الجمعية تلاوة ملخص لتقرير الهيئة فى حالة عدم
 حضور ممثل عن الهيئة .
 الوقائع المصریة – العدد ) ١٢٨تابع( فى ١٢یونیة سنة ٢٠٢٥ ٢٨$b490$, now()::date, 'active' FROM ins_art______________69______2025__________22;
WITH ins_art______________69______2025__________23 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 23, NULL, $b491$مواعيد إعداد وعرض وتقديم القوائم المالية والمستندات المرفقة بها للهيئة
تلتزم الشركة بموافاة الهيئة قبل شهر من موعد انعقاد الجمعية العامة بالقوائم
المالية السنوية والإفصاحات المرفقة بها وفق ًا لمعايير المحاسبة المصرية ،وتقرير
بشأنها من أحد مراقبى الحسابات المقيدين بالقسم الأول من سجل مراقبى الحسابات
المنظم بقرار مجلس إدارة الهيئة رقم ٢٤٤لسنة ٢٠٢٣المشار إليه ،وتقرير مجلس
الإدارة عن نشاط الشركة ،وموعد ومكان انعقاد الجمعية العامة وجدول أعمالها ،
 وجميع المستندات التى تقدم للمساهمين أو من فى حكمهم عن أعمال الشركة .
وللهيئة إبداء ملاحظاتها على القوائم المالية ،وكذا على أى من البيانات
والمستندات الواردة بهذا القرار وإخطار الشركة بملاحظاتها ،على أن يعرض ذلك
 على الجمعية العامة للشركة .
وتلتزم الشركة بموافاة الهيئة بالقوائم المالية السنوية لها خلال خمسة عشر يوما
 من تاريخ انتهاء الثلاثة أشهر التالية لانتهاء السنة المالية مرفق بها المستندات الآتية :
 -١تقرير مراقب الحسابات عن تلك القوائم حال تعديلها من قبل الجمعية
 العامة للشركة .
 -٢حجم العمليات التى توسطت الشركة فيها خلال العام ،وحجم العمولات
 التى حصلت عليها .
 -٣مقدار العمولات المستحقة لها من كافة شركات التأمين أو إعادة التأمين على
 حدة عن السنة المالية المنقضية ،ومقدار مديونية كل شركة .
 -٤أسماء شركات التأمين أو إعادة التأمين التى تعاملت معها خلال السنة
 المالية المنقضية .$b491$
  FROM laws WHERE law_no = 69 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
