INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (89, 2025, $t513$بشأن الشروط والمعايير الواجب توافرها فى أعضاء مجالس إدارة شركات التأمين أو إعادة التأمين، والشروط والمعايير الواجب توافرها فى القائمين على الإدارة التنفيذية المسئولين عن الأعمال والوظائف الفنية$t513$, $t513$بشأن الشروط والمعايير الواجب توافرها فى أعضاء مجالس إدارة شركات التأمين أو إعادة التأمين، والشروط والمعايير الواجب توافرها فى القائمين على الإدارة التنفيذية المسئولين عن الأعمال والوظائف الفنية$t513$, 'insurance', 'in_force', $u513$https://fra.gov.eg/wp-content/uploads/2025/06/نشر-قرار-رقم-89-لسنة-2025-بالوقائع.pdf$u513$, NULL)
ON CONFLICT (law_no, law_year) DO NOTHING;

