WITH ins_art______________89______2025__________7 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 7, NULL, $b520$إجراءات تعيين القائمين على الإدارة التنفيذية المسئولين عن
 الأعمال والوظائف الفنية
تلتزم شركات التأمين أو إعادة التأمين بموافاة الهيئة بأسماء المرشحين لشغل أى
 من الوظائف المشار إليها بالمادة الخامسة من هذا القرار ،مرفق ًا به المستندات الآتية :
 -١صورة بطاقة الرقم القومى للمرشح .
 -٢سيرة ذاتية تفصيلية للمرشح .
 -٣بيان حالة تفصيلى للمرشح .
 -٤صورة من المؤهل الدراسى ،والشهادات المهنية والدورات الحاصل
 عليها المرشح .
 -٥الإفصاح على النموذج المعد لذلك عن مدى وجود صلة قرابة حتى الدرجة
 الرابعة مع أى من أعضاء مجلس إدارة الشركة أو العاملين بها .
 -٦تعهد بالانضمام للمنصة الإلكترونية للمهنيين المنشأة لدى الهيئة فور إتاحتها بها .
 -٧أى بيانات أو مستندات أخرى ترى الهيئة ضرورة تقديمها .
وفى جميع الأحوال ،تلتزم الشركات المشار إليها بالاطلاع على القائمة المعدة
لدى الهيئة بشأن المخالفين للتشريعات المنظمة للأنشطة المالية غير المصرفية قبل
 موافاة الهيئة بأسماء المرشحين لشغل أى من الوظائف المشار إليها .
 الوقائع المصریة – العدد ) ١٢٨تابع( فى ١٢یونیة سنة ٢٠٢٥ ٥٨$b520$
  FROM laws WHERE law_no = 89 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
